import { z } from 'zod';
const TodoBaru = z.object({ judul: z.string().trim().min(1), prioritas: z.enum(['rendah', 'sedang', 'tinggi']).default('sedang') });
const TodoUbah = z.object({ selesai: z.boolean() }).partial();
const data = [];
const service = {
  async tambah(penggunaId, masukan) {
    const h = TodoBaru.safeParse(masukan);
    if (!h.success) throw Object.assign(new Error('Data tidak valid'), { status: 400 });
    const t = { id: data.length + 1, penggunaId, selesai: false, ...h.data };
    data.push(t);
    return t;
  },
  async ubah(penggunaId, id, masukan) {
    const t = data.find((x) => x.id === id);
    if (!t || t.penggunaId !== penggunaId) throw Object.assign(new Error('Todo tidak ada'), { status: 404 });
    const h = TodoUbah.safeParse(masukan);
    if (!h.success) throw Object.assign(new Error('Data tidak valid'), { status: 400 });
    return Object.assign(t, h.data);
  },
};
const a = await service.tambah(1, { judul: ' Beli kopi ' });
const b = await service.tambah(1, { judul: 'Rapat', prioritas: 'tinggi' });
console.log(a.prioritas, b.prioritas);
try {
  await service.ubah(2, 1, { selesai: true });
} catch (e) {
  console.log(e.status);
}

